def execute_step(attempt):
    # the acting half of the loop: producing a raw result
    return "" if attempt == 1 else "Order A100 shipped on Monday."

def reflect_on_result(result, goal):
    # the evaluating half: checking the result against the goal
    if not result or len(result) < 10:
        return False, "Result is empty or too short to satisfy the goal."
    return True, "Result satisfies the goal."

def run_with_reflection(goal, max_attempts=3):
    for attempt in range(1, max_attempts + 1):
        result = execute_step(attempt)
        sufficient, reason = reflect_on_result(result, goal)
        print(f"Attempt {attempt}: result={result!r}, sufficient={sufficient} ({reason})")
        if sufficient:
            return result
    return "Failed after max attempts."

goal = "Find the shipping status of order A100"
final_result = run_with_reflection(goal)
print("\nFinal result:", final_result)
